-- Generated by tools/build-important.py; presentation summaries, original sources stay in the registry.
return {["schema"]=1,["source_date"]="2026-10-28",["cards"]={{["id"]="radio",["title"]="Радиокоды и маркировки",["subtitle"]="Коротко передать ситуацию и понять эфир",["highlights"]={"10-55 — остановка · 10-57 — погоня","Коды, обозначения экипажей и станции"},["sections"]={{["id"]="decimal",["title"]="Десятичные коды",["rows"]={}},{["id"]="situational",["title"]="Ситуативные коды",["rows"]={}},{["id"]="three",["title"]="Трёхзначные коды",["rows"]={}},{["id"]="units",["title"]="Маркировки и связь",["rows"]={{["id"]="tac",["title"]="Как передавать доклад",["text"]="Назовите свой юнит, местоположение и суть ситуации. При погоне уточняйте направление, автомобиль или приметы и переход в TAC. Смысл кодов берётся из действующего мануала, а не из старого справочника.",["refs"]={"rules:manual-current:4:110:1"}}}}},["actions"]={}},{["id"]="traffic",["title"]="Трафик-стоп и погоня",["subtitle"]="10-55 · 10-57 VICTOR / FOXTROT",["highlights"]={"Остановить → представиться → назвать причину","Документы и решение по установленным фактам"},["sections"]={{["id"]="stop",["title"]="Обычная остановка",["rows"]={{["id"]="grounds",["title"]="Сначала основание",["text"]="Проверка документов и остановка должны иметь основание. Укажите наблюдавшееся нарушение, ориентировку или другое предусмотренное законом обстоятельство. Само удобство проверки не заменяет основание.",["refs"]={"rules:manual-current:4:230:1","articles:police604:21"}},{["id"]="sequence",["title"]="Порядок 10-55",["text"]="Подайте требование остановиться. Безопасно расположите крузер и передайте доклад. При подходе выполните предусмотренные мануалом действия у фары, оцените салон и обстановку. Представьтесь, покажите жетон, сообщите причину остановки и запросите документы. Решение — беседа, штраф или задержание — зависит от фактов.",["refs"]={"rules:manual-current:4:230:2"}}}},{["id"]="pursuit",["title"]="Погоня",["rows"]={{["id"]="coordination",["title"]="10-57 VICTOR / FOXTROT",["text"]="VICTOR — автомобильная погоня, FOXTROT — пешая. Передавайте направление и описание цели; согласуйте TAC и координацию. Ведущий юнит не должен терять контроль за дорогой ради передачи длинного доклада. Манёвры проводятся с соблюдением полномочий и условий мануала.",["refs"]={"rules:manual-current:4:250:1"}}}},{["id"]="tires",["title"]="Огонь по колёсам",["rows"]={{["id"]="ordinary",["title"]="Обычная погоня по мануалу",["text"]="В мануале: пять предупреждений о применении манёвра через мегафон; отдельный парный патруль; погоня более десяти минут; преследование вне города. В том же тексте есть отдельное исключение для скоростного автомобиля Full PT и запрет общественных мест. Эти условия не являются разрешением стрелять в любой ситуации.",["refs"]={"rules:manual-current:4:250:1"}},{["id"]="different",["title"]="Не смешивайте разные ситуации",["text"]="В правилах устранения ограбления бизнеса, ограбления АЗС и задержания указано как минимум одно предупреждение перед огнём по колёсам. Условия конкретного раздела показываются отдельно от обычной погони. При расхождении применимости уточните порядок у руководства; счётчик PA сам не разрешает применение оружия.",["refs"]={"rules:reg-current:01","rules:reg-current:02","rules:reg-current:03","rules:reg-current:04","rules:reg-current:05"}}}}},["actions"]={{["kind"]="operational",["label"]="Открыть пульт «Трафик и погоня»",["value"]="traffic"},{["kind"]="operational",["label"]="Выбрать причину остановки",["value"]="grounds"}}},{["id"]="risk",["title"]="10-66 и манёвры",["subtitle"]="Остановка повышенного риска",["highlights"]={"Скоординировать экипажи и исключить перекрёстный огонь","Манёвр — при наличии его условий"},["sections"]={{["id"]="stop",["title"]="Порядок 10-66",["rows"]={{["id"]="reason",["title"]="Когда повышается риск",["text"]="Остановка повышенного риска применяется в предусмотренных мануалом обстоятельствах: сведения об оружии или преступлении, остановка после погони. Доложите о ситуации и запросите необходимые силы.",["refs"]={"rules:manual-current:4:240:1"}},{["id"]="orders",["title"]="Команды и задержание",["text"]="Согласуйте построение и секторы. Потребуйте заглушить двигатель, выбросить ключи и показать руки; выход контролируется по одному. Проверка пояса, положения людей и подход офицеров должны исключать перекрёстный огонь. Если требования игнорируются, дальнейшее решение зависит от тактической обстановки и предусмотренных мануалом средств.",["refs"]={"rules:manual-current:4:240:1"}}}},{["id"]="maneuvers",["title"]="Манёвры",["rows"]={{["id"]="slam",["title"]="СЛЭМ",["text"]="Обгон с постепенным снижением скорости. Нужна возможность продолжить координацию при неудаче и ещё одна наземная патрульная единица в визуальном контакте.",["refs"]={"rules:manual-current:4:250:1"}},{["id"]="box",["title"]="БОКС и параллелинг",["text"]="Движущаяся коробочка окружает цель и постепенно снижает скорость. При параллелинге AIR или ведущий юнит координирует, остальные патрули занимают возможные направления. Учитывайте распоряжения старшего по ситуации.",["refs"]={"rules:manual-current:4:250:1"}},{["id"]="ram",["title"]="РЭМ",["text"]="Намеренное столкновение для обездвиживания автомобиля при экстренной необходимости. В предоставленном мануале запрещён в городе.",["refs"]={"rules:manual-current:4:250:1"}},{["id"]="pit",["title"]="ПИТ",["text"]="Удар в заднюю часть автомобиля для разворота. Нужны возможность продолжения координации и ещё один наземный патруль в прямом визуальном контакте. Может быть инициирован ведущим координацию, но запрещён старшим. В городе мануал предусматривает случай очевидной угрозы гражданам.",["refs"]={"rules:manual-current:4:250:1"}}}}},["actions"]={{["kind"]="operational",["label"]="Открыть пульт ситуации",["value"]="traffic"}}},{["id"]="rights",["title"]="Задержание и права",["subtitle"]="Основание · Миранда · адвокат · звонок · обыск",["highlights"]={"Адвокат: ответ 5 минут, прибытие 10 минут","Телефонный звонок — до 3 минут"},["sections"]={{["id"]="grounds",["title"]="Основание",["rows"]={{["id"]="basis",["title"]="Что сообщить задержанному",["text"]="Установите предусмотренное законом основание, сообщите причину и нарушение, разъясните право на защитника и обжалование. Номер игрового пункта или наличие звёзд не заменяют правовую квалификацию.",["refs"]={"articles:police604:22","articles:constitution725:10"}}}},{["id"]="rights",["title"]="Миранда и реализация прав",["rows"]={{["id"]="miranda",["title"]="Разъяснить права",["text"]="Права зачитываются перед арестом и вопросами о составе преступления. Данные, удостоверяющие личность, можно спросить до Миранды. Если права не поняты, разъясните второй раз и сообщите, что повторного разъяснения больше не будет.",["refs"]={"rules:manual-current:4:210:1"}},{["id"]="lawyer",["title"]="Адвокат: два разных ожидания",["text"]="Передайте запрос через департамент или старшего. Если ответа нет пять минут, процедура продолжается. При ответе адвоката процессуальный час приостанавливается до приезда; если он не прибыл за десять минут, процедура продолжается. Сообщение об отсутствии свободных адвокатов или невозможности приезда также позволяет продолжить процедуру в порядке мануала.",["refs"]={"rules:manual-current:4:210:1"}},{["id"]="call",["title"]="Один телефонный звонок",["text"]="Предоставьте до трёх минут до начала ареста. Цель — вызов адвоката или уведомление близких родственников; по требованию офицера задержанный сообщает цель. Офицер или напарник находится рядом и контролирует ситуацию.",["refs"]={"rules:manual-current:4:210:1"}}}},{["id"]="search",["title"]="Первичный и полный обыск",["rows"]={{["id"]="initial",["title"]="Первичный обыск",["text"]="При обоснованном задержании проверьте верхнюю одежду на оружие в безопасном положении. Не подменяйте первичную проверку полным изъятием вещей.",["refs"]={"rules:manual-current:4:220.20:1"}},{["id"]="full",["title"]="Полный обыск",["text"]="При задержании/аресте человек уже в наручниках. Полный обыск направлен на поиск вещей для изъятия; соблюдайте порядок работы с найденными предметами и их фиксации.",["refs"]={"rules:manual-current:4:220.30:1"}}}}},["actions"]={{["kind"]="operational",["label"]="Открыть права и таймеры",["value"]="rights"},{["kind"]="operational",["label"]="Выбрать основание задержания",["value"]="grounds"}}},{["id"]="force",["title"]="Применение силы и тайзер",["subtitle"]="Необходимость, соразмерность и условия",["highlights"]={"Тайзер: до 20 м, интервал выстрелов 5 секунд","Два выстрела → RP-перезарядка"},["sections"]={{["id"]="force",["title"]="Применение силы",["rows"]={{["id"]="deescalation",["title"]="Начните с оценки угрозы",["text"]="Где это безопасно и осуществимо, используйте время, дистанцию, связь и деэскалацию. Сила должна быть объективно разумной и соразмерной обстоятельствам. Схема PA не создаёт нового основания для применения силы.",["refs"]={"rules:manual-current:4:260.10:1"}},{["id"]="deadly",["title"]="Смертельная сила",["text"]="Применяется при предусмотренных законом и мануалом основаниях для защиты человеческой жизни. Оцените непосредственную угрозу, окружение и риск для посторонних. Не превращайте любое неподчинение или попытку убежать в автоматическое разрешение стрелять.",["refs"]={"rules:manual-current:4:260.10:1","articles:police604:25"}}}},{["id"]="taser",["title"]="Taser / SD Pistol",["rows"]={{["id"]="distance",["title"]="Дистанция и предупреждение",["text"]="Раздел V: до двадцати метров, при системной видимости никнейма. До применения нужно как минимум одно предупреждение о возможном применении средств или оружия при невыполнении законного требования.",["refs"]={"rules:reg-current:01","rules:reg-current:02","rules:reg-current:03","rules:reg-current:04","rules:reg-current:05"}},{["id"]="cadence",["title"]="Пять секунд — между выстрелами",["text"]="Применять не чаще одного раза в пять секунд. При промахе следующий выстрел делает напарник либо тот же офицер спустя пять секунд. Из этого пункта не следует отдельное обязательное ожидание пяти секунд после предупреждения.",["refs"]={"rules:reg-current:01","rules:reg-current:02","rules:reg-current:03","rules:reg-current:04","rules:reg-current:05"}},{["id"]="reload",["title"]="Перезарядка",["text"]="Максимум два выстрела на один Taser, после чего обязательна RP-отыгровка перезарядки. Промах не отменяет ограничения.",["refs"]={"rules:reg-current:01","rules:reg-current:02","rules:reg-current:03","rules:reg-current:04","rules:reg-current:05"}},{["id"]="combat",["title"]="Активная перестрелка",["text"]="В общем случае Taser запрещён в активной перестрелке. В п. 5.5 перечислены исключения: выстрел в спину/бок либо багоюз стрельбы противником (+C, слайды и т. п.; полуотвод разрешён). Правило Full PT из автомобильной погони сюда не переносится.",["refs"]={"rules:reg-current:01","rules:reg-current:02","rules:reg-current:03","rules:reg-current:04","rules:reg-current:05"}}}}},["actions"]={}},{["id"]="wanted",["title"]="Розыск, маска и пеленгация",["subtitle"]="IC-основание и технические звёзды",["highlights"]={"/su ID раздел подпункт — последнее число не звёзды","OOC-звёзды: только для RP-пеленгации"},["sections"]={{["id"]="ic",["title"]="IC-розыск",["rows"]={{["id"]="identity",["title"]="Известная личность или приметы",["text"]="Передайте диспетчеру установленные RP-путём персональные данные либо приметы. По п. 6.2 диспетчер составляет фоторобот и устанавливает личность. Никнейм, TAB и Discord сами не являются IC-источником. Передача сведений требует RP-отыгровки.",["refs"]={"rules:reg-current:01","rules:reg-current:02","rules:reg-current:03","rules:reg-current:04","rules:reg-current:05"}},{["id"]="life",["title"]="Текущая RP-ситуация",["text"]="После собственной смерти объявлять розыск в рамках той же ситуации запрещено. Состояние ранения с возможностью реанимации не приравнивается в PA к подтверждённому респавну. Выбранный ID может находиться далеко: расстояние само по себе не заменяет проверку основания.",["refs"]={"rules:reg-current:01","rules:reg-current:02","rules:reg-current:03","rules:reg-current:04","rules:reg-current:05"}}}},{["id"]="mask",["title"]="RP-маска",["rows"]={{["id"]="mask",["title"]="Нужны оба признака",["text"]="Полная RP-маска: системная /mask (серый клист) и закрытое лицо. Один признак без другого считается NonRP-маской и не мешает фотороботу. Для полной маски предусмотрено исключение: личность достоверно установлена до её надевания и человек не терялся из виду.",["refs"]={"rules:reg-current:01","rules:reg-current:02","rules:reg-current:03","rules:reg-current:04","rules:reg-current:05"}}}},{["id"]="ooc",["title"]="OOC и /setmark",["rows"]={{["id"]="phone",["title"]="Технический розыск",["text"]="OOC-звёзды допускаются только для /setmark в рамках RP-пеленгации при известном по IC номере телефона и соответствующей отыгровке. Выключенный телефон не позволяет отслеживание.",["refs"]={"rules:reg-current:01","rules:reg-current:02","rules:reg-current:03","rules:reg-current:04","rules:reg-current:05"}},{["id"]="limits",["title"]="Чего нельзя делать",["text"]="OOC-звёзды нельзя использовать для /pt, Alcatraz или иных целей. После завершения пеленгации их требуется снять. Сначала проверьте, есть ли собственный IC-розыск: техническая очистка не должна молча удалить реальные обвинения.",["refs"]={"rules:reg-current:01","rules:reg-current:02","rules:reg-current:03","rules:reg-current:04","rules:reg-current:05"}},{["id"]="sequence",["title"]="Порядок в PA",["text"]="Откройте пеленгацию, подтвердите источник номера и отыгровку. При необходимости добавьте технический розыск отдельным решением. Получение сервером команды ещё не доказывает успешную пеленгацию; снятие технических звёзд контролируется по результату.",["refs"]={"rules:reg-current:01","rules:reg-current:02","rules:reg-current:03","rules:reg-current:04","rules:reg-current:05"}}}}},["actions"]={{["kind"]="wanted",["label"]="Открыть помощник розыска",["value"]=nil},{["kind"]="mark",["label"]="Открыть пеленгацию",["value"]=nil}}},{["id"]="fines",["title"]="Штрафы АК и ПДД",["subtitle"]="Санкции и условия из текущего АК",["highlights"]={"Нарушение → условия → допустимая санкция","ПМ и игровая сумма — разные величины"},["sections"]={{["id"]="all",["title"]="Все основные составы",["rows"]={}},{["id"]="road",["title"]="ПДД и дорога",["rows"]={}},{["id"]="public",["title"]="Общественный порядок",["rows"]={}},{["id"]="authority",["title"]="Оружие и власть",["rows"]={}},{["id"]="procedure",["title"]="Порядок применения",["rows"]={{["id"]="one",["title"]="Одно деяние и квалификация",["text"]="Если деяние содержит признаки преступления и административного нарушения, применяется уголовная ответственность. Одно и то же деяние не должно одновременно становиться основанием административного и уголовного наказания.",["refs"]={"articles:AK:149"}},{["id"]="detention",["title"]="Административное задержание",["text"]="Максимум три часа, если иной срок прямо не установлен законом; освобождение — после достижения цели. Основания перечислены отдельно в статье 132. Это не произвольное наказание за любой отказ сотрудничать.",["refs"]={"articles:AK:131","articles:AK:132"}},{["id"]="pm",["title"]="Расчёт суммы",["text"]="Штраф выбирается в пределах применимой ветви с учётом предупреждения, повторности и дополнительных санкций. Денежный эквивалент ПМ задаётся в настройках PA; при неизвестном курсе калькулятор не придумывает сумму.",["refs"]={"rules:reg-current:01","rules:reg-current:02","rules:reg-current:03","rules:reg-current:04","rules:reg-current:05"}}}}},["actions"]={{["kind"]="fine",["label"]="Открыть форму штрафа",["value"]=nil}}},{["id"]="catalog",["title"]="Статьи УК и пункты /su",["subtitle"]="13 игровых разделов, 31 причина",["highlights"]={"Игровой пункт и правовая квалификация различаются","Звёзды — по наблюдавшемуся меню сервера"},["sections"]={{["id"]="all",["title"]="Все пункты",["rows"]={}}},["actions"]={{["kind"]="wanted",["label"]="Открыть помощник розыска",["value"]=nil}}},{["id"]="commands",["title"]="Команды и RP-отыгровка",["subtitle"]="Проверенная таблица раздела XI",["highlights"]={"50 команд: 21 с RP, 29 без отдельного RP","Синтаксис команды проверяется отдельно"},["sections"]={{["id"]="all",["title"]="Все 50 команд",["rows"]={}},{["id"]="required",["title"]="Требуют RP",["rows"]={}},{["id"]="free",["title"]="Без отдельного RP",["rows"]={}},{["id"]="extra",["title"]="Дополнительные команды",["rows"]={}}},["actions"]={}},{["id"]="service",["title"]="Нормы службы и законы",["subtitle"]="Состав, операции и права граждан",["highlights"]={"Гетто: задержание от 3 сотрудников, с исключением","Сохраняйте основания и доказательства"},["sections"]={{["id"]="crew",["title"]="Состав и опасный район",["rows"]={{["id"]="business",["title"]="Ограбление бизнеса",["text"]="На устранение ограбления бизнеса направляется патруль минимум из двух сотрудников. Это правило относится к указанной ситуации и не устанавливает общий минимум для всех вызовов 911.",["refs"]={"rules:reg-current:01","rules:reg-current:02","rules:reg-current:03","rules:reg-current:04","rules:reg-current:05"}},{["id"]="danger",["title"]="Задержание в опасном районе",["text"]="П. 9.3: от трёх сотрудников; разрешено объединяться FBI/МО/ПД. Если человек скрывается в опасном районе во время погони, допускается продолжение преследования и задержание в одиночку. Отдельно допускается одиночное патрулирование, если иные положения или законодательство его не ограничивают.",["refs"]={"rules:reg-current:01","rules:reg-current:02","rules:reg-current:03","rules:reg-current:04","rules:reg-current:05"}},{["id"]="recording",["title"]="Доказательства",["text"]="Соблюдайте требования видеофиксации конкретной операции. Текст /me о включении камеры не включает реальную запись игры. Сохранённая команда PA также не является доказательством результата сервера.",["refs"]={"rules:reg-current:01","rules:reg-current:02","rules:reg-current:03","rules:reg-current:04","rules:reg-current:05"}}}},{["id"]="raids",["title"]="Рейды и спецоперации",["rows"]={{["id"]="conditions",["title"]="До рейда",["text"]="Проверьте основание дела/материалы, установленный состав, одобрение администрации и судебный ордер либо предусмотренное исключение. В разделе IV указан минимум десять участников и ограничение повторного рейда на одну фракцию раз в семь дней с указанными исключениями.",["refs"]={"rules:reg-current:01","rules:reg-current:02","rules:reg-current:03","rules:reg-current:04","rules:reg-current:05"}},{["id"]="time",["title"]="В источнике расходятся часы",["text"]="П. 4.3 называет 14:00–22:00. П. 10.9 запрещает рейды 20:00–13:00. PA показывает оба положения и не объявляет одно из них отменённым. Уточните применимый порядок перед операцией.",["refs"]={"rules:reg-current:01","rules:reg-current:02","rules:reg-current:03","rules:reg-current:04","rules:reg-current:05"}},{["id"]="assault",["title"]="Решение о штурме",["text"]="Нужны RP-основание, оценка риска и соблюдение переговорного порядка/исключений. Предоставленные пункты не устанавливают универсальные таймеры «два предупреждения по минуте» для АЗС или «пять минут до штурма банка». Не используйте их как основание разрешения.",["refs"]={"rules:reg-current:01","rules:reg-current:02","rules:reg-current:03","rules:reg-current:04","rules:reg-current:05"}}}},{["id"]="laws",["title"]="Конституция и законы",["rows"]={{["id"]="appeal",["title"]="Причина, защитник и обжалование",["text"]="Конституция 10.3: задержанному разъясняются основания, вменяемое нарушение, право на защитника и обжалование. Доступ к материалам дела регулируется отдельно, в том числе статьёй 11.",["refs"]={"articles:constitution725:10","articles:constitution725:11"}},{["id"]="assembly",["title"]="Мирное собрание",["text"]="Статья 12 защищает мирные собрания. Отсутствие предварительного разрешения само по себе не доказывает незаконность мероприятия; проверяйте фактические признаки применимого состава.",["refs"]={"articles:constitution725:12"}},{["id"]="hierarchy",["title"]="Взаимодействие ведомств",["text"]="Полномочия EPD и FBI проверяются по законам и Конституции. Само указание сотрудника другого ведомства не отменяет установленные ограничения и порядок принятия решений.",["refs"]={"articles:police604:1","articles:fbi:1","articles:constitution725:60"}},{["id"]="covert",["title"]="Негласные мероприятия",["text"]="Для негласных мероприятий и внедрения применяются специальные основания и согласования. Особый порядок в отношении руководства и старшего состава нельзя заменять обычным решением патруля.",["refs"]={"articles:police604:28.1","articles:police604:28.2","articles:constitution725:61"}}}}},["actions"]={}}},["command_matrix"]={{["command"]="/invite",["rp_required"]=true},{["command"]="/uninvite",["rp_required"]=true},{["command"]="/fmenu",["rp_required"]=false},{["command"]="/fmission",["rp_required"]=false},{["command"]="/r",["rp_required"]=false},{["command"]="/rn",["rp_required"]=false},{["command"]="/f",["rp_required"]=false},{["command"]="/fn",["rp_required"]=false},{["command"]="/su",["rp_required"]=true},{["command"]="/clear",["rp_required"]=true},{["command"]="/cuff",["rp_required"]=true},{["command"]="/uncuff",["rp_required"]=true},{["command"]="/arrest",["rp_required"]=true},{["command"]="/push",["rp_required"]=true},{["command"]="/m",["rp_required"]=false},{["command"]="/find",["rp_required"]=false},{["command"]="/takelic",["rp_required"]=true},{["command"]="/skip",["rp_required"]=true},{["command"]="/unskip",["rp_required"]=false},{["command"]="/ud",["rp_required"]=false},{["command"]="/frisk",["rp_required"]=true},{["command"]="/take",["rp_required"]=true},{["command"]="/fwarn",["rp_required"]=true},{["command"]="/unfwarn",["rp_required"]=true},{["command"]="/unmask",["rp_required"]=true},{["command"]="/fwarnoff",["rp_required"]=false},{["command"]="/d",["rp_required"]=false},{["command"]="/taser",["rp_required"]=false},{["command"]="/division",["rp_required"]=false},{["command"]="/undivision",["rp_required"]=false},{["command"]="/black",["rp_required"]=false},{["command"]="/unblack",["rp_required"]=f